style.css:
@-moz-document domain("github.com") {
/* Background colors */
    body {
        background-color: #333333;
        color: #e0e0e0;
        font-family: Arial, sans-serif;
    }

    /* Header Style */
    header, .Header {
        background-color: #5c2d91;
        border-bottom: 2px solid #00b3b8;
        color: #ffffff;
    }

    /* Navigation bar styles */
    nav, .Header-nav {
        background-color: #5c2d91;
    }

    .Header-item {
        color: #ffffff;
    }

    .Header-item:hover {
        background-color: #00b3b8;
        color: #333333;
    }

    /* Links */
    a {
        color: #00b3b8;
        text-decoration: none;
    }

    a:hover {
        color: #5c2d91;
    }

    /* Buttons */
    button, .btn, .btn-primary {
        background-color: #5c2d91;
        border: none;
        color: #ffffff;
        padding: 10px 15px;
        border-radius: 5px;
    }

    button:hover, .btn:hover, .btn-primary:hover {
        background-color: #00b3b8;
    }

    /* Code block styles */
    pre, code {
        background-color: #222222;
        color: #e0e0e0;
        padding: 10px;
        border-radius: 5px;
    }

    /* Sidebar Styles */
    .sidebar {
        background-color: #222222;
    }

    .sidebar-item {
        color: #e0e0e0;
    }

    .sidebar-item:hover {
        background-color: #5c2d91;
        color: #ffffff;
    }

    /* Footer */
    footer {
        background-color: #222222;
        color: #e0e0e0;
    }

    /* Form Styles */
    input, textarea, select {
        background-color: #444444;
        border: 1px solid #5c2d91;
        color: #e0e0e0;
        padding: 8px;
        border-radius: 5px;
    }

    input[type="submit"] {
        background-color: #5c2d91;
        color: white;
    }

    input[type="submit"]:hover {
        background-color: #00b3b8;
    }

    /* Tables */
    table {
        border-collapse: collapse;
        width: 100%;
        margin: 20px 0;
    }

    th, td {
        padding: 10px;
        text-align: left;
    }

    th {
        background-color: #5c2d91;
        color: #ffffff;
    }

    tr:nth-child(even) {
        background-color: #444444;
    }

    tr:hover {
        background-color: #00b3b8;
        color: #333333;
    }
}
